        'list_themes': False,
        'diag': False,
        'cache_help': False,
        'tabs': 4,
    }

    i = 1
    skip_next = False

    take_arg = {
        '-l', '--language', '--fallback-syntax', '-H', '--highlight-line', 
        '--file-name', '--diff-context', '--tabs', '--wrap', '--terminal-width', 
        '--color', '--italic-text', '--decorations', '--paging', '--pager', 
        '-m', '--map-syntax', '--ignored-suffix', '--theme', '--theme-light', 
        '--theme-dark', '--squeeze-limit', '--strip-ansi', '--style', '-r', 
        '--line-range', '--completion', '--nonprintable-notation', '--binary'
    }

    if len(args) > 1 and args[1] == 'cache':
        if '--help' in args or '-h' in args:
            flags['cache_help'] = True
        return [], flags

    while i < len(args):
        arg = args[i]

        if skip_next:
            skip_next = False
            i += 1
            continue

        if arg == '--':
            files.extend(args[i+1:])
            break

        if arg.startswith('-') and arg != '-':
            if '=' in arg:
                key, val = arg.split('=', 1)
                if key in ('--tabs',):
                    flags['tabs'] = int(val) if val.isdigit() else 0
            else:
                if arg in take_arg:
                    if arg in ('--tabs',):
                        if i+1 < len(args) and args[i+1].isdigit():
                            flags['tabs'] = int(args[i+1])
                    skip_next = True
                else:
                    if not arg.startswith('--'):
                        for c in arg[1:]:
                            if c == 'A': flags['A'] = True
                            elif c == 'n': flags['n'] = True
                            elif c == 'h': flags['help'] = True
                            elif c == 'V': flags['version'] = True
                            elif c == 'L': flags['list_langs'] = True
                            elif c in ('l', 'H', 'm', 'r', 'd', 'S', 'f', 's', 'p', 'u', 'E'):
                                if c in ('l', 'H', 'm', 'r'):
                                    skip_next = True
                                    break
                    else:
                        if arg == '--show-all': flags['A'] = True
                        elif arg == '--number': flags['n'] = True
                        elif arg == '--help': flags['help'] = True
                        elif arg == '--version': flags['version'] = True
                        elif arg == '--list-languages': flags['list_langs'] = True
                        elif arg == '--list-themes': flags['list_themes'] = True
                        elif arg == '--diagnostic': flags['diag'] = True
        else:
            files.append(arg)

        i += 1

    return files, flags

